import{g as a,ad as n,r as p,A as e}from"./chunks/framework.79nw0c7c.js";const h=JSON.parse('{"title":"Utilities","description":"","frontmatter":{},"headers":[],"relativePath":"docs/other/utilities.md","filePath":"docs/other/utilities.md","lastUpdated":1789506983000}'),c={name:"docs/other/utilities.md"};function l(t,s,o,d,r,i){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to “Utilities”">​</a></h1><p>Some common utilities that are useful in building frontend apps.</p><h2 id="debounce" tabindex="-1">debounce <a class="header-anchor" href="#debounce" aria-label="Permalink to “debounce”">​</a></h2><p>Creates a function that will run only once in the specified number of wait time (milliseconds). In the following example, if you run <code>debouncedInput</code> function every time the user presses a key, it will run only once in every <code>500ms</code>.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">debounce</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_50ecpt">function</span><span class="s_indoxt"> onInput</span><span class="s_13ahmt">(</span><span class="s_fsg3al">e</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_1th9sy">  // do something with input event</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> debouncedInput</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> debounce</span><span class="s_13ahmt">(</span><span class="s_22m8k2">onInput</span><span class="s_1jjt6x">,</span><span class="s_40mev6"> 500</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="dayjs-dayjslocal" tabindex="-1">dayjs / dayjsLocal <a class="header-anchor" href="#dayjs-dayjslocal" aria-label="Permalink to “dayjs / dayjsLocal”">​</a></h2><p><code>dayjs</code> is a re-export of <a href="https://day.js.org/" target="_blank" rel="noreferrer">Day.js</a>, pre-loaded with the plugins the library and most apps need: <code>relativeTime</code>, <code>localizedFormat</code>, <code>isToday</code>, <code>duration</code>, <code>utc</code>, <code>timezone</code>, <code>advancedFormat</code>, <code>customParseFormat</code>. Import it instead of adding your own <code>dayjs</code> dependency, so every date in the app shares one set of plugins.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">dayjs</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> label</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> dayjs</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">2024-01-15</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1jjt6x">.</span><span class="s_indoxt">format</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">MMMM D, YYYY</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1th9sy"> // &quot;January 15, 2024&quot;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>dayjsLocal</code> converts a datetime string stored in the server&#39;s timezone (<code>setConfig(&#39;systemTimezone&#39;, …)</code>) into the browser&#39;s local timezone (<code>setConfig(&#39;localTimezone&#39;, …)</code>, falling back to the browser&#39;s own). Called with no argument, it returns &quot;now&quot; in the local timezone. Without a <code>systemTimezone</code> configured, it behaves exactly like <code>dayjs</code>.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">dayjsLocal</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> setConfig</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">systemTimezone</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">UTC</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> local</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> dayjsLocal</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">2024-01-15 10:00:00</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1th9sy"> // 10:00 UTC, shown in the browser&#39;s zone</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>dayjs</code> and <code>dayjsLocal</code> are the two public helpers. The opposite conversion, <code>dayjsSystem</code>, is internal to the library and is not exported.</p><h2 id="call" tabindex="-1">call <a class="header-anchor" href="#call" aria-label="Permalink to “call”">​</a></h2><p>Calls a whitelisted method on the server and resolves to its <code>message</code>. The method is a dotted path; an argument object becomes the JSON request body.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">call</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> count</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_indoxt"> call</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">frappe.client.get_count</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Pass a path starting with <code>/</code> to hit it directly instead of <code>/api/method/…</code>.</p><p>A third argument takes <code>headers</code> (merged over the defaults, winning over anything from <a href="#configuration"><code>setConfig(&#39;requestHeaders&#39;)</code></a>) and <code>onError</code>, which receives <code>{ response, status, error }</code> for a failed HTTP response. The promise rejects either way — <code>onError</code> is for reporting, not for recovery.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">call</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> toast</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_29n2kq">await</span><span class="s_indoxt"> call</span><span class="s_13ahmt">(</span></span>
<span class="line"><span class="s_w1p9wo">  &#39;</span><span class="s_2575z4">my_app.api.save</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  {</span><span class="s_r4oegk"> name</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  {</span><span class="s_indoxt"> onError</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> error</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_22m8k2"> toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">error</span><span class="s_13ahmt">(</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">messages</span><span class="s_13ahmt">[</span><span class="s_40mev6">0</span><span class="s_13ahmt">])</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>The rejection is a <code>FrappeResourceError</code>: a plain <code>Error</code> carrying <code>exc_type</code>, <code>exc</code>, <code>status</code>, <code>response</code>, and <code>messages</code> (the server&#39;s <code>_server_messages</code>, already parsed).</p><h2 id="frapperequest" tabindex="-1">frappeRequest <a class="header-anchor" href="#frapperequest" aria-label="Permalink to “frappeRequest”">​</a></h2><p>The transport <code>call</code> is built on, for requests <code>call</code> doesn&#39;t shape — a <code>GET</code>, a non-method URL, a request you need to abort.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">frappeRequest</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> doc</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_indoxt"> frappeRequest</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/resource/ToDo/TODO-0001</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  method</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">GET</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Options: <code>url</code> (required), <code>method</code> (defaults to <code>POST</code>), <code>params</code> (query string on <code>GET</code>, JSON body otherwise), <code>headers</code>, <code>signal</code>, <code>credentials</code>, <code>responseType</code> (<code>&#39;json&#39;</code> or <code>&#39;response&#39;</code>), and the <code>onError</code> / <code>onServerMessages</code> callbacks. It sets the <code>Accept</code>, <code>Content-Type</code>, <code>X-Frappe-Site-Name</code> and CSRF headers, unwraps <code>message</code> from the response, and throws a <code>FrappeResourceError</code> on failure.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h3><p>Both <code>call</code> and <code>frappeRequest</code> read these through <code>setConfig</code>. <code>getConfig</code> reads a value back — useful when one part of the app sets a value another part depends on.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">getConfig</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> setConfig</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> toast</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1th9sy">// point requests at a remote site during local development</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">requestBaseUrl</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">https://my-site.frappe.cloud</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_1th9sy">// merged into every request; pass a function for values that change</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">requestHeaders</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> ({</span><span class="s_r4oegk"> Authorization</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> \`</span><span class="s_2575z4">token </span><span class="s_20l85h">\${</span><span class="s_22m8k2">key</span><span class="s_20l85h">}</span><span class="s_2575z4">:</span><span class="s_20l85h">\${</span><span class="s_22m8k2">secret</span><span class="s_20l85h">}</span><span class="s_w1p9wo">\`</span><span class="s_13ahmt"> }))</span></span>
<span class="line"><span class="s_1th9sy">// called with the server&#39;s _server_messages on a successful response</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">serverMessagesHandler</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> (</span><span class="s_fsg3al">messages</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_22m8k2"> messages</span><span class="s_1jjt6x">.</span><span class="s_indoxt">forEach</span><span class="s_13ahmt">(</span><span class="s_22m8k2">toast</span><span class="s_13ahmt">))</span></span>
<span class="line"></span>
<span class="line"><span class="s_indoxt">getConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">requestBaseUrl</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span><span class="s_1th9sy"> // &#39;https://my-site.frappe.cloud&#39;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Setting <code>requestBaseUrl</code> makes relative requests cross-origin and defaults them to <code>credentials: &#39;include&#39;</code>, so the server has to send <code>Access-Control-Allow-Credentials: true</code> and a non-wildcard origin. If you authenticate with a token header instead, pass <code>credentials: &#39;omit&#39;</code> per request.</p><h2 id="frapperequesterror" tabindex="-1">FrappeResourceError <a class="header-anchor" href="#frapperequesterror" aria-label="Permalink to “FrappeResourceError”">​</a></h2><p>The error <a href="#call"><code>call</code></a>, <a href="#frapperequest"><code>frappeRequest</code></a> and the v1 <a href="./../data-fetching/resource">resources</a> raise. A plain <code>Error</code> carrying the transport fields of the failed request: <code>messages</code> (the server messages array), <code>exc_type</code>, <code>exc</code>, <code>status</code> and the raw <code>response</code>. The name says the layer that raises it: both errors are server responses, so request versus response named nothing. The <a href="./../migration#errors-renamed">migration guide</a> has the rename.</p><p>It is a TypeScript <code>interface</code>, not a class: the resource layer throws <code>new Error(...)</code> and assigns those fields. So it types a caught error (<code>catch (error) { const e = error as FrappeResourceError }</code> — a catch clause variable cannot carry a type annotation) but <code>error instanceof FrappeResourceError</code> does not compile, and <code>error.name</code> is <code>&quot;Error&quot;</code>. Test a field instead, for example <code>e.exc_type === &#39;PermissionError&#39;</code>.</p><p>It stays separate from <code>FrappeResponseError</code> below, which the v2 composables raise and which is a real class. <a href="./../data-fetching/use-call#which-error-class">The error table</a> says which API raises which.</p><h2 id="frapperesponseerror" tabindex="-1">FrappeResponseError <a class="header-anchor" href="#frapperesponseerror" aria-label="Permalink to “FrappeResponseError”">​</a></h2><p>The error <a href="./../data-fetching/use-call"><code>useCall</code></a>, <a href="./../data-fetching/use-doc"><code>useDoc</code></a> and <a href="./../data-fetching/use-list"><code>useList</code></a> raise on a Frappe error response — set on <code>.error</code> and the reason <code>submit()</code>/<code>execute()</code> rejects with. An <code>Error</code> with <code>title</code>, <code>type</code>, <code>exception</code> and <code>indicator</code> from the server&#39;s response.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FrappeResponseError</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> useCall</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> rename</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> useCall</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">/api/method/frappe.client.rename_doc</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  method</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">POST</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  immediate</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> false</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_indoxt">  onError</span><span class="s_13ahmt">(</span><span class="s_fsg3al">error</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_50ecpt">    if</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_2ekfrt"> instanceof</span><span class="s_euu481"> FrappeResponseError</span><span class="s_13ahmt">) {</span></span>
<span class="line"><span class="s_22m8k2">      console</span><span class="s_1jjt6x">.</span><span class="s_indoxt">log</span><span class="s_13ahmt">(</span><span class="s_22m8k2">error</span><span class="s_1jjt6x">.</span><span class="s_11933w">title</span><span class="s_1jjt6x">,</span><span class="s_22m8k2"> error</span><span class="s_1jjt6x">.</span><span class="s_11933w">type</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_13ahmt">    }</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><h2 id="frappeui-plugin" tabindex="-1">FrappeUI plugin <a class="header-anchor" href="#frappeui-plugin" aria-label="Permalink to “FrappeUI plugin”">​</a></h2><p>An optional Vue plugin with one boolean option. It installs the v1 resources Options API mixin — the <code>resources: { … }</code> component option, <code>this.$resources</code>, and the <code>$getResource</code> / <code>$getDoc</code> / <code>$getListResource</code> / <code>$refetchResource</code> helpers.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// main.js</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">createApp</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">vue</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FrappeUI</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> app</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> createApp</span><span class="s_13ahmt">(</span><span class="s_22m8k2">App</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> resources</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span></code></pre></div><p><code>resources</code> is a boolean: <code>true</code> installs the mixin, <code>false</code> or no options leaves it out. Earlier versions typed it as an object and never read what was in it. The object form is a type error now. It still installs the mixin at runtime, so an app that misses the change keeps working. <code>npx -p frappe-ui data-v1 ./src</code> rewrites it.</p><p>You do not need it otherwise. Components, the imperative <code>dialog</code> and <code>toast</code> APIs, and every Composition API data helper work without installing anything — wrap your app in <a href="./../getting-started"><code>FrappeUIProvider</code></a> instead. Passing an option the plugin doesn&#39;t accept logs a warning in development.</p><h2 id="usefileupload-fileuploadhandler" tabindex="-1">useFileUpload / FileUploadHandler <a class="header-anchor" href="#usefileupload-fileuploadhandler" aria-label="Permalink to “useFileUpload / FileUploadHandler”">​</a></h2><p>Two lower-level primitives for posting a file to Frappe&#39;s upload endpoint without the <a href="./../components/fileuploader"><code>FileUploader</code></a> component — reach for them for a custom trigger, multi-file upload, or a fully headless flow. <code>FileUploader</code> is the ready-made UI built on top of <code>FileUploadHandler</code>.</p><p>Uploads default to <strong>private</strong> — an upload with no stated <code>private</code> resolves to <code>is_private=1</code> on the server. Pass <code>private: false</code> only for intentionally public files.</p><h3 id="usefileupload" tabindex="-1">useFileUpload <a class="header-anchor" href="#usefileupload" aria-label="Permalink to “useFileUpload”">​</a></h3><p>A composable with reactive upload state.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">useFileUpload</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_1jjt6x"> {</span><span class="s_295sjd"> upload</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> state</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> isUploading</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> progress</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> error</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> result</span><span class="s_1jjt6x">,</span><span class="s_295sjd"> reset</span><span class="s_1jjt6x"> }</span><span class="s_2ekfrt"> =</span></span>
<span class="line"><span class="s_indoxt">  useFileUpload</span><span class="s_13ahmt">()</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">async</span><span class="s_50ecpt"> function</span><span class="s_indoxt"> onFile</span><span class="s_13ahmt">(</span><span class="s_fsg3al">file</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">  await</span><span class="s_indoxt"> upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_r4oegk">doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> docname</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-0001</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_1th9sy">  // result.value (same as state.result) now holds the uploaded file</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p><code>upload(file, options)</code> resets state, uploads the file, and resolves to the uploaded file&#39;s record (or rejects with an <a href="#uploaderror"><code>UploadError</code></a>). <code>state</code> — and the <code>isUploading</code> / <code>progress</code> / <code>error</code> / <code>result</code> computed refs read from it — update as the request runs. <code>error</code> is an <code>UploadError</code> or <code>null</code>. <code>reset()</code> clears <code>state</code> back to its initial values without uploading anything.</p><p><code>options</code> (<code>UploadOptions</code>):</p><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>private</code></td><td><code>boolean</code></td><td>Defaults to <code>true</code>. Pass <code>false</code> for public files.</td></tr><tr><td><code>folder</code></td><td><code>string</code></td><td>Defaults to <code>Home</code>.</td></tr><tr><td><code>doctype</code> / <code>docname</code> / <code>fieldname</code></td><td><code>string</code></td><td>Attaches the upload to a document field.</td></tr><tr><td><code>file_url</code></td><td><code>string</code></td><td>Replaces the file at an existing URL.</td></tr><tr><td><code>method</code></td><td><code>string</code></td><td>A whitelisted method to call instead of the default upload handler.</td></tr><tr><td><code>type</code></td><td><code>string</code></td><td>Passed through to the upload endpoint as-is.</td></tr><tr><td><code>upload_endpoint</code></td><td><code>string</code></td><td>Defaults to <code>/api/method/upload_file</code>.</td></tr><tr><td><code>optimize</code></td><td><code>boolean</code></td><td>Resize the image server-side.</td></tr><tr><td><code>max_width</code> / <code>max_height</code></td><td><code>number</code></td><td>Applied when <code>optimize</code> is set.</td></tr><tr><td><code>params</code></td><td><code>object</code></td><td>Extra form fields, appended as-is.</td></tr><tr><td><code>signal</code></td><td><code>AbortSignal</code></td><td>Cancels the upload.</td></tr><tr><td><code>onProgress</code></td><td><code>(p: { loaded, total, percent }) =&gt; void</code></td><td>Called on every progress tick.</td></tr></tbody></table><h3 id="fileuploadhandler" tabindex="-1">FileUploadHandler <a class="header-anchor" href="#fileuploadhandler" aria-label="Permalink to “FileUploadHandler”">​</a></h3><p>An event-emitter class, for callers that want <code>.on(…)</code> instead of reactive state — this is what <code>FileUploader</code> itself uses internally.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FileUploadHandler</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> handler</span><span class="s_2ekfrt"> =</span><span class="s_2ekfrt"> new</span><span class="s_indoxt"> FileUploadHandler</span><span class="s_13ahmt">()</span></span>
<span class="line"><span class="s_22m8k2">handler</span><span class="s_1jjt6x">.</span><span class="s_indoxt">on</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">start</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> {})</span></span>
<span class="line"><span class="s_22m8k2">handler</span><span class="s_1jjt6x">.</span><span class="s_indoxt">on</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">progress</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> (</span><span class="s_1jjt6x">{</span><span class="s_fsg3al"> uploaded</span><span class="s_1jjt6x">,</span><span class="s_fsg3al"> total</span><span class="s_1jjt6x"> }</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> {})</span></span>
<span class="line"><span class="s_22m8k2">handler</span><span class="s_1jjt6x">.</span><span class="s_indoxt">on</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">error</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> (</span><span class="s_fsg3al">error</span><span class="s_13ahmt">)</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> {})</span></span>
<span class="line"><span class="s_22m8k2">handler</span><span class="s_1jjt6x">.</span><span class="s_indoxt">on</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">finish</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> ()</span><span class="s_50ecpt"> =&gt;</span><span class="s_13ahmt"> {})</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> result</span><span class="s_2ekfrt"> =</span><span class="s_29n2kq"> await</span><span class="s_22m8k2"> handler</span><span class="s_1jjt6x">.</span><span class="s_indoxt">upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span></code></pre></div><p><code>upload(file, options)</code> takes the same <code>UploadOptions</code> as <code>useFileUpload</code> and resolves to the uploaded file&#39;s record, rejecting with an <a href="#uploaderror"><code>UploadError</code></a> on failure. The events fire alongside the promise, for callers that want to hook progress without awaiting: <code>start</code> (request began), <code>progress</code> (<code>{ uploaded, total }</code>), <code>error</code> (the server&#39;s error text, if any), <code>finish</code> (upload succeeded).</p><h2 id="uploaderror" tabindex="-1">UploadError <a class="header-anchor" href="#uploaderror" aria-label="Permalink to “UploadError”">​</a></h2><p>Every upload failure rejects with this class: <code>upload</code>, <code>useFileUpload</code> and <code>FileUploadHandler</code> all raise it, and <code>useFileUpload</code>&#39;s <code>state.error</code> holds it.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>kind</code></td><td><code>&#39;file-size&#39; | &#39;network&#39; | &#39;server&#39; | &#39;abort&#39;</code></td><td>What failed. Branch on this instead of matching the message.</td></tr><tr><td><code>status</code></td><td><code>number | undefined</code></td><td>The HTTP status, for <code>kind: &#39;server&#39;</code>.</td></tr><tr><td><code>messages</code></td><td><code>string[]</code></td><td>The server messages, parsed. Empty for the other kinds.</td></tr><tr><td><code>response</code></td><td><code>unknown</code></td><td>The parsed response body, for <code>kind: &#39;server&#39;</code>.</td></tr></tbody></table><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">upload</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> UploadError</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">async</span><span class="s_50ecpt"> function</span><span class="s_indoxt"> send</span><span class="s_13ahmt">(</span><span class="s_fsg3al">file</span><span class="s_13ahmt">)</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_50ecpt">  try</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">    return</span><span class="s_29n2kq"> await</span><span class="s_indoxt"> upload</span><span class="s_13ahmt">(</span><span class="s_22m8k2">file</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> { </span><span class="s_r4oegk">doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> docname</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">TODO-0001</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> })</span></span>
<span class="line"><span class="s_13ahmt">  } </span><span class="s_50ecpt">catch</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_13ahmt">) {</span></span>
<span class="line"><span class="s_50ecpt">    if</span><span class="s_13ahmt"> (</span><span class="s_22m8k2">error</span><span class="s_2ekfrt"> instanceof</span><span class="s_euu481"> UploadError</span><span class="s_50ecpt"> &amp;&amp;</span><span class="s_22m8k2"> error</span><span class="s_1jjt6x">.</span><span class="s_11933w">kind</span><span class="s_50ecpt"> ===</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">file-size</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">) {</span></span>
<span class="line"><span class="s_22m8k2">      toast</span><span class="s_1jjt6x">.</span><span class="s_indoxt">error</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">That file is too large.</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">)</span></span>
<span class="line"><span class="s_29n2kq">      return</span></span>
<span class="line"><span class="s_13ahmt">    }</span></span>
<span class="line"><span class="s_50ecpt">    throw</span><span class="s_22m8k2"> error</span></span>
<span class="line"><span class="s_13ahmt">  }</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div>`,55)])])}const u=a(c,[["render",l]]);export{h as __pageData,u as default};
